  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Present Progressive, Future Plans, Careers and Traditions$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nPart 1: Explain how to form the present participle and the present progressive, give ten participles including three irregular ones, and write five sentences.\nPart 2: Explain how to form the future tense, conjugate one regular and one irregular verb, and write six sentences about your future.\nPart 3: Write a Spanish introduction of at least eight sentences for a job interview, using career and technology words and polite forms.\nPart 4: Write at least 120 words in English about one Spanish speaking holiday or tradition, with at least eight Spanish words, and describe how to ask about it respectfully.\nPart 5: Explain how Proverbs 16:3 and Colossians 3:23 guide your plans for work and service.\nPart 6: Explain why it is wrong to describe all Spanish speakers as the same, and give an example.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 10 points. Part 6: 10 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Present Progressive, Future Plans, Careers and Traditions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Plans and Callings$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a job or ministry you hope to have, (2) shares at least three Spanish sentences about your future using the future tense, (3) explains how Spanish could help you serve in that work, and (4) connects your answer to Proverbs 16:3 or Colossians 3:23. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can learning about another culture's holidays help the church welcome its neighbors?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Plans and Callings$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: The Present Progressive$j$, $j${"questions": [{"q": "The participle of hablar is:", "options": ["Hablaendo", "Hablando", "Hablar", "Hablado"]}, {"q": "The participle of leer is:", "options": ["Leiendo", "Leyendo", "Leando", "Leendo"]}, {"q": "Estoy orando means:", "options": ["I am praying", "I will pray", "I prayed", "I pray every day"]}, {"q": "The participle of dormir is:", "options": ["Dormiendo", "Duermendo", "Durmiendo", "Dormendo"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Present Progressive$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,2}'::int[], array[$j$Ar verbs take ando.$j$,$j$Between vowels, iendo becomes yendo.$j$,$j$Estar plus a participle shows an action in progress.$j$,$j$Dormir changes o to u in the participle.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Present Progressive$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: The Future Tense$j$, $j${"questions": [{"q": "The yo future of hablar is:", "options": ["Hablaré", "Hablé", "Hablo", "Hablaría"]}, {"q": "The yo future of tener is:", "options": ["Tendré", "Tuvé", "Tengaré", "Teneré"]}, {"q": "Ellos harán means:", "options": ["They were doing", "They do", "They did", "They will do"]}, {"q": "Future endings are the same for:", "options": ["Only ir verbs", "Ar, er and ir verbs", "Only ar verbs", "Only irregular verbs"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Future Tense$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,1}'::int[], array[$j$Add é to the whole infinitive.$j$,$j$Tener has the irregular stem tendr.$j$,$j$Harán is the future of hacer.$j$,$j$The future uses the same endings for all verbs.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Future Tense$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Careers, Technology and the Interview$j$, $j${"questions": [{"q": "Me gustaría trabajar con ustedes means:", "options": ["I worked with you", "I will work alone", "I would like to work with you", "I work with you"]}, {"q": "La contraseña is the:", "options": ["Screen", "File", "Phone", "Password"]}, {"q": "In an interview, address the interviewer with:", "options": ["Usted", "Tú", "Ellos", "Vos only"]}, {"q": "El abogado is a:", "options": ["Lawyer", "Doctor", "Mechanic", "Teacher"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Careers, Technology and the Interview$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,0}'::int[], array[$j$Me gustaría expresses a polite wish.$j$,$j$Contraseña means password.$j$,$j$Usted is polite and formal.$j$,$j$Abogado means lawyer.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Careers, Technology and the Interview$j$ on conflict (item_id) do nothing;
